contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint collectAmount, uint unlockTime) public payable {
        require(address(this).balance >= putAmount);

        // Deposit funds and set an unlock time through the public Put entry.
        c.Put{value: putAmount}(unlockTime);

        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        bool reverted;

        if (beforeBalance >= c.MinSum() && beforeBalance >= collectAmount && block.timestamp > beforeUnlock) {
            try c.Collect(collectAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }

            (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

            if (!reverted) {
                assert(afterBalance == beforeBalance - collectAmount);
            } else {
                assert(afterBalance == beforeBalance && afterUnlock == beforeUnlock);
            }
        } else {
            try c.Collect(collectAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }

            (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

            assert(reverted && afterBalance == beforeBalance && afterUnlock == beforeUnlock);
        }
    }

    receive() external payable {}
}

